create or replace function hnk_private.validate_day061_completion_v2(p_evidence jsonb,p_expected_source_sha text)
returns void language plpgsql set search_path='' as $$
declare b jsonb; inv jsonb; r jsonb; a jsonb; c jsonb; m jsonb; legacy jsonb; k text; stopped boolean; ref text;
begin
 if jsonb_typeof(p_evidence) is distinct from 'object' then raise exception 'day061_v2_evidence_object_required'; end if;
 if exists(select 1 from jsonb_object_keys(p_evidence) x where x not in ('protocol_version','source_sha','session_id','mode','baseline','reorganization','after','comparison','middle','private_vault_entry_ref','private_vault_e2ee_confirmed','practice_record_privacy_confirmed','voluntary_completion_confirmed','final_safety_clear_confirmed','safety_stop_occurred','safety_stop_reason')) then raise exception 'day061_v2_unknown_top_field'; end if;
 if p_evidence->>'protocol_version' is distinct from 'HNK-CHOKMAH-D061-V2' then raise exception 'day061_v2_protocol_invalid'; end if;
 if p_evidence->>'source_sha' is distinct from p_expected_source_sha or p_expected_source_sha is distinct from '12e4c2da623f2f78d3fea3ff65e23f9446f9784b' then raise exception 'day061_v2_source_sha_invalid'; end if;
 if nullif(btrim(p_evidence->>'session_id'),'') is null then raise exception 'day061_v2_session_required'; end if;
 if coalesce(p_evidence->>'mode','first_completion') not in ('first_completion','revisit') then raise exception 'day061_v2_mode_invalid'; end if;
 if p_evidence->'practice_record_privacy_confirmed' is distinct from 'true'::jsonb or p_evidence->'voluntary_completion_confirmed' is distinct from 'true'::jsonb or p_evidence->'final_safety_clear_confirmed' is distinct from 'true'::jsonb then raise exception 'day061_v2_completion_boundary_required'; end if;
 if jsonb_typeof(p_evidence->'safety_stop_occurred') is distinct from 'boolean' then raise exception 'day061_v2_safety_stop_flag_invalid'; end if;
 if p_evidence->>'safety_stop_reason' not in ('NONE','IMPORTANT_ALERT_SILENCED','DISTRESS','RESPONSIBILITY_RISK','OTHER') then raise exception 'day061_v2_safety_reason_invalid'; end if;
 stopped:=(p_evidence->>'safety_stop_occurred')::boolean;
 if stopped and p_evidence->>'safety_stop_reason'='NONE' then raise exception 'day061_v2_safety_reason_required'; end if;
 if not stopped and p_evidence->>'safety_stop_reason'<>'NONE' then raise exception 'day061_v2_safety_reason_without_stop'; end if;
 ref:=p_evidence->>'private_vault_entry_ref';
 if ref is not null then
   if ref!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then raise exception 'day061_v2_vault_ref_invalid'; end if;
   if p_evidence->'private_vault_e2ee_confirmed' is distinct from 'true'::jsonb then raise exception 'day061_v2_vault_e2ee_required'; end if;
 elsif p_evidence ? 'private_vault_e2ee_confirmed' then raise exception 'day061_v2_vault_flag_without_ref'; end if;
 b:=p_evidence->'baseline';if jsonb_typeof(b) is distinct from 'object' then raise exception 'day061_v2_baseline_required'; end if;
 if exists(select 1 from jsonb_object_keys(b) x where x not in ('duration_seconds','inventory','interruptions','unlocks','anxiety','return_to_task','useful_alerts','completed_confirmed')) then raise exception 'day061_v2_baseline_unknown_field'; end if;
 if b->'completed_confirmed' is distinct from 'true'::jsonb then raise exception 'day061_v2_baseline_incomplete'; end if;
 foreach k in array array['duration_seconds','interruptions','unlocks','useful_alerts'] loop if not coalesce(hnk_private.jsonb_is_nonnegative_integer(b->k),false) then raise exception 'day061_v2_baseline_count_invalid:%',k; end if; end loop;
 foreach k in array array['anxiety','return_to_task'] loop if not coalesce(hnk_private.jsonb_is_nonnegative_integer(b->k),false) or (b->>k)::integer>10 then raise exception 'day061_v2_baseline_score_invalid:%',k; end if; end loop;
 inv:=b->'inventory';if jsonb_typeof(inv) is distinct from 'object' then raise exception 'day061_v2_inventory_required'; end if;
 if exists(select 1 from jsonb_object_keys(inv) x where x not in ('essential','useful','dispensable')) then raise exception 'day061_v2_inventory_unknown_field'; end if;
 foreach k in array array['essential','useful','dispensable'] loop if not coalesce(hnk_private.jsonb_is_nonnegative_integer(inv->k),false) then raise exception 'day061_v2_inventory_count_invalid:%',k; end if; end loop;
 r:=p_evidence->'reorganization';if jsonb_typeof(r) is distinct from 'object' then raise exception 'day061_v2_reorganization_required'; end if;
 if exists(select 1 from jsonb_object_keys(r) x where x not in ('completed_confirmed','home_screen_reorganized_confirmed','noncritical_noise_reduced_confirmed','critical_security_preserved_confirmed','security_auth_preserved_confirmed','health_family_emergency_preserved_confirmed','essential_work_preserved_confirmed','no_automatic_critical_change_confirmed','explicit_user_action_confirmed','focus_periods_configured_count')) then raise exception 'day061_v2_reorganization_unknown_field'; end if;
 foreach k in array array['completed_confirmed','home_screen_reorganized_confirmed','noncritical_noise_reduced_confirmed','critical_security_preserved_confirmed','security_auth_preserved_confirmed','health_family_emergency_preserved_confirmed','essential_work_preserved_confirmed','no_automatic_critical_change_confirmed','explicit_user_action_confirmed'] loop if r->k is distinct from 'true'::jsonb then raise exception 'day061_v2_reorganization_boundary_required:%',k; end if; end loop;
 if not coalesce(hnk_private.jsonb_is_nonnegative_integer(r->'focus_periods_configured_count'),false) or (r->>'focus_periods_configured_count')::integer<>2 then raise exception 'day061_v2_exactly_two_focus_periods_required'; end if;
 a:=p_evidence->'after';if jsonb_typeof(a) is distinct from 'object' then raise exception 'day061_v2_after_required'; end if;
 if exists(select 1 from jsonb_object_keys(a) x where x not in ('duration_seconds','interruptions','unlocks','anxiety','return_to_task','useful_alerts','completed_confirmed','similar_activity_when_possible_confirmed','no_mid_window_readjustment_confirmed','important_alert_mistake_occurred','important_alert_restored_immediately')) then raise exception 'day061_v2_after_unknown_field'; end if;
 foreach k in array array['completed_confirmed','similar_activity_when_possible_confirmed','no_mid_window_readjustment_confirmed'] loop if a->k is distinct from 'true'::jsonb then raise exception 'day061_v2_after_boundary_required:%',k; end if; end loop;
 foreach k in array array['duration_seconds','interruptions','unlocks','useful_alerts'] loop if not coalesce(hnk_private.jsonb_is_nonnegative_integer(a->k),false) then raise exception 'day061_v2_after_count_invalid:%',k; end if; end loop;
 foreach k in array array['anxiety','return_to_task'] loop if not coalesce(hnk_private.jsonb_is_nonnegative_integer(a->k),false) or (a->>k)::integer>10 then raise exception 'day061_v2_after_score_invalid:%',k; end if; end loop;
 if jsonb_typeof(a->'important_alert_mistake_occurred') is distinct from 'boolean' or jsonb_typeof(a->'important_alert_restored_immediately') is distinct from 'boolean' then raise exception 'day061_v2_alert_restore_flags_invalid'; end if;
 if (a->>'important_alert_mistake_occurred')::boolean and not (a->>'important_alert_restored_immediately')::boolean then raise exception 'day061_v2_important_alert_restore_required'; end if;
 c:=p_evidence->'comparison';if jsonb_typeof(c) is distinct from 'object' then raise exception 'day061_v2_comparison_required'; end if;
 if exists(select 1 from jsonb_object_keys(c) x where x not in ('completed_confirmed','null_or_worse_result_accepted_confirmed','fewer_notifications_not_moral_score_confirmed','checking_habit_independent_allowed_confirmed','sustainable_configuration_selected_confirmed','review_days','review_time_bucket')) then raise exception 'day061_v2_comparison_unknown_field'; end if;
 foreach k in array array['completed_confirmed','null_or_worse_result_accepted_confirmed','fewer_notifications_not_moral_score_confirmed','checking_habit_independent_allowed_confirmed','sustainable_configuration_selected_confirmed'] loop if c->k is distinct from 'true'::jsonb then raise exception 'day061_v2_comparison_boundary_required:%',k; end if; end loop;
 if not coalesce(hnk_private.jsonb_is_nonnegative_integer(c->'review_days'),false) or (c->>'review_days')::integer<>7 then raise exception 'day061_v2_review_days_must_equal_7'; end if;
 if c->>'review_time_bucket' not in ('MORNING','AFTERNOON','EVENING','CUSTOM_PRIVATE') then raise exception 'day061_v2_review_time_bucket_invalid'; end if;
 m:=p_evidence->'middle';if jsonb_typeof(m) is distinct from 'object' then raise exception 'day061_v2_middle_required'; end if;
 if exists(select 1 from jsonb_object_keys(m) x where x not in ('psalm_10_1_confirmed','he_he_aleph_confirmed','phone_functions_named_count','dispensable_noise_types_named_count','critical_alerts_reconfirmed','thanks_to_god_confirmed','conscious_return_confirmed')) then raise exception 'day061_v2_middle_unknown_field'; end if;
 foreach k in array array['psalm_10_1_confirmed','he_he_aleph_confirmed','critical_alerts_reconfirmed','thanks_to_god_confirmed','conscious_return_confirmed'] loop if m->k is distinct from 'true'::jsonb then raise exception 'day061_v2_middle_boundary_required:%',k; end if; end loop;
 if not coalesce(hnk_private.jsonb_is_nonnegative_integer(m->'phone_functions_named_count'),false) or (m->>'phone_functions_named_count')::integer<>3 then raise exception 'day061_v2_three_phone_functions_required'; end if;
 if not coalesce(hnk_private.jsonb_is_nonnegative_integer(m->'dispensable_noise_types_named_count'),false) or (m->>'dispensable_noise_types_named_count')::integer<>3 then raise exception 'day061_v2_three_noise_types_required'; end if;
 legacy:=jsonb_build_object('protocol_completed',true,'return_confirmed',m->'conscious_return_confirmed','baseline_completed',b->'completed_confirmed','manual_reorganization_completed',r->'completed_confirmed','after_window_completed',a->'completed_confirmed','comparison_completed',c->'completed_confirmed','critical_alerts_preserved',r->'critical_security_preserved_confirmed','security_auth_preserved',r->'security_auth_preserved_confirmed','family_emergency_preserved',r->'health_family_emergency_preserved_confirmed','no_automatic_critical_change',r->'no_automatic_critical_change_confirmed','sustainable_configuration_selected',c->'sustainable_configuration_selected_confirmed','review_time_selected',true,'safety_clear',p_evidence->'final_safety_clear_confirmed','interruptions_before',b->'interruptions','interruptions_after',a->'interruptions','unlocks_before',b->'unlocks','unlocks_after',a->'unlocks');
 perform hnk_private.validate_day061_scalar_evidence_v1(legacy);
end$$;
create or replace function hnk_private.enforce_hahaiah_057_061_scalar_evidence() returns trigger language plpgsql security definer set search_path='' as $$declare v_existing boolean;v_source_sha text;v_status text;begin if new.day not in (57,58,59,60,61) or new.state not in ('evidence_pending','complete') then return new;end if;select exists(select 1 from public.day_completions where user_id=new.user_id and day=new.day) into v_existing;if v_existing then return new;end if;select source_sha,status into v_source_sha,v_status from public.codex_days where day=new.day;if v_status is distinct from 'canon' then raise exception 'hahaiah_canonical_day_not_available';end if;if new.day=57 then if v_source_sha is distinct from 'deb6305d38b89a4168ad5cff083d2b96e7a7fec4' then raise exception 'day057_canonical_source_sha_mismatch';end if;if new.evidence->>'protocol_version'='HNK-CHOKMAH-D057-V2' then perform hnk_private.validate_day057_completion_v2(new.evidence,v_source_sha);else perform hnk_private.validate_day057_scalar_evidence_v1(new.evidence);end if;elsif new.day=58 then if v_source_sha is distinct from 'e32753a57daab23d378e881451194b0dd77d8aac' then raise exception 'day058_canonical_source_sha_mismatch';end if;if new.evidence->>'protocol_version'='HNK-CHOKMAH-D058-V2' then perform hnk_private.validate_day058_completion_v2(new.evidence,v_source_sha);else perform hnk_private.validate_day058_scalar_evidence_v1(new.evidence);end if;elsif new.day=59 then if v_source_sha is distinct from 'e0b9b51cac81012e4511e6394c6f3dff7f50aaf8' then raise exception 'day059_canonical_source_sha_mismatch';end if;if new.evidence->>'protocol_version'='HNK-CHOKMAH-D059-V2' then perform hnk_private.validate_day059_completion_v2(new.evidence,v_source_sha);else perform hnk_private.validate_day059_scalar_evidence_v1(new.evidence);end if;elsif new.day=60 then if v_source_sha is distinct from 'e98e8925c8e03555c39b033813999d6a488149a9' then raise exception 'day060_canonical_source_sha_mismatch';end if;if new.evidence->>'protocol_version'='HNK-CHOKMAH-D060-V2' then perform hnk_private.validate_day060_completion_v2(new.evidence,v_source_sha);else perform hnk_private.validate_day060_scalar_evidence_v1(new.evidence);end if;else if v_source_sha is distinct from '12e4c2da623f2f78d3fea3ff65e23f9446f9784b' then raise exception 'day061_canonical_source_sha_mismatch';end if;if new.evidence->>'protocol_version'='HNK-CHOKMAH-D061-V2' then perform hnk_private.validate_day061_completion_v2(new.evidence,v_source_sha);else perform hnk_private.validate_day061_scalar_evidence_v1(new.evidence);end if;end if;return new;end$$;
do $$ declare v_def text;v_old text;v_new text;begin select pg_get_functiondef('hnk_private.validate_completion_contract_v2(text,jsonb,text)'::regprocedure) into v_def;if position('when ''day061_v2''' in v_def)=0 then v_old:='  else raise exception ''unsupported_completion_validator:%'',p_validator_key;';if position(v_old in v_def)=0 then raise exception 'day061_dispatcher_patch_anchor_missing';end if;v_new:='  when ''day061_v2'' then perform hnk_private.validate_day061_completion_v2(p_evidence,p_expected_source_sha);'||E'\n'||v_old;v_def:=replace(v_def,v_old,v_new);execute v_def;end if;end$$;
insert into hnk_private.completion_contract_registry(completion_contract_id,quest_definition_id,day,canonical_source_sha,contract_version,validator_key,status) values('HNK-CHOKMAH-D061-COMP-V2','HNK-CHOKMAH-D061-V2',61,'12e4c2da623f2f78d3fea3ff65e23f9446f9784b','2.0.0','day061_v2','draft') on conflict(completion_contract_id) do update set quest_definition_id=excluded.quest_definition_id,day=excluded.day,canonical_source_sha=excluded.canonical_source_sha,contract_version=excluded.contract_version,validator_key=excluded.validator_key,status='draft',updated_at=now();
